function DamageAssessmentUpload() {
  const [uploadProgress, setUploadProgress] = React.useState(0);
  const [uploadedFiles, setUploadedFiles] = React.useState([]);

  // Placeholder upload logic
  const handleFileUpload = (event) => {
    const files = Array.from(event.target.files);
    setUploadedFiles(files);
    // Simulate upload progress
    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      setUploadProgress(progress);
      if (progress >= 100) {
        clearInterval(interval);
      }
    }, 200);
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100">
      <div className="bg-white shadow-md rounded px-8 pt-6 pb-8 mb-4 w-full max-w-md">
        <h2 className="text-2xl font-bold mb-6 text-gray-700">Upload Damage Photos/Videos</h2>

        <div className="mb-6">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="mediaUpload">
            Select Files
          </label>
          <input type="file" id="mediaUpload" multiple onChange={handleFileUpload} />
        </div>

        {uploadProgress > 0 && (
          <div className="mb-4">
            <label className="block text-gray-700 text-sm font-bold mb-2">Upload Progress</label>
            <progress value={uploadProgress} max="100"></progress>
            <p className="text-gray-600 text-sm">{uploadProgress}%</p>
          </div>
        )}

        {uploadedFiles.length > 0 && (
          <div className="mb-6">
            <h3 className="text-lg font-semibold mb-2 text-gray-700">Uploaded Files</h3>
            <ul className="list-disc list-inside text-gray-600">
              {uploadedFiles.map((file, index) => (
                <li key={index}>{file.name}</li>
              ))}
            </ul>
          </div>
        )}

        <div className="flex items-center justify-between">
          <button
            className="bg-gray-500 hover:bg-gray-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
            type="button"
            disabled={uploadProgress < 100}
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
}

