import React, { useState, useEffect } from 'react';

const ClaimSubmissionPrototype = () => {
  const [step, setStep] = useState('start'); // 'start', 'details', 'upload', 'assessing', 'results', 'repairer', 'complete'
  const [claimType, setClaimType] = useState(null); // 'auto' or 'property'
  const [claimDetails, setClaimDetails] = useState({ date: '', location: '', description: '' });
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isUploading, setIsUploading] = useState(false);
  const [assessmentResult, setAssessmentResult] = useState(null);
  const [selectedRepairer, setSelectedRepairer] = useState(null);
  const [isBooking, setIsBooking] = useState(false);

  const STEPS = [
    { id: 'start', name: 'Claim Type' },
    { id: 'details', name: 'Incident Details' },
    { id: 'upload', name: 'Upload Media' },
    { id: 'results', name: 'AI Assessment' },
    { id: 'repairer', name: 'Select Repairer' },
    { id: 'complete', name: 'Confirmation' },
  ];

  const currentStepIndex = STEPS.findIndex(s => s.id === step || (step === 'assessing' && s.id === 'results'));

  // Mock Data
  const repairers = [
    { id: 1, name: 'Sydney Premium Smash Repairs', location: 'Alexandria, NSW', rating: 4.8, distance: '5 km' },
    { id: 2, name: 'North Shore Auto Body', location: 'Artarmon, NSW', rating: 4.9, distance: '12 km' },
    { id: 3, name: 'Parramatta Fine Finish', location: 'Parramatta, NSW', rating: 4.7, distance: '25 km' },
  ];

  const handleStartClaim = (type) => {
    setClaimType(type);
    setStep('details');
  };

  const handleDetailsSubmit = (e) => {
    e.preventDefault();
    setStep('upload');
  };

  const handleFileUpload = () => {
    setIsUploading(true);
    const interval = setInterval(() => {
      setUploadProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          setTimeout(() => {
            setStep('assessing');
          }, 500);
          return 100;
        }
        return prev + 10;
      });
    }, 200);
  };

  const handleConfirmBooking = () => {
    setIsBooking(true);
    setTimeout(() => {
        setIsBooking(false);
        setStep('complete');
    }, 1500);
  }

  useEffect(() => {
    if (step === 'assessing') {
      const assessmentTimer = setTimeout(() => {
        setAssessmentResult({
          status: 'Pre-approved',
          fraudScore: 12, // Low risk
          severity: 'Moderate',
          estimatedCost: '2,450.00 AUD',
          damages: ['Front Bumper Scuff', 'Right Headlight Cracked', 'Hood Dent'],
        });
        setStep('results');
      }, 3500);
      return () => clearTimeout(assessmentTimer);
    }
  }, [step]);

  const isDetailsFormValid = claimDetails.date && claimDetails.location && claimDetails.description.length > 10;

  const Header = () => (
    <header className="bg-white shadow-sm">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2">
           <svg className="h-8 w-8 text-blue-600" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75m-3-7.036A11.959 11.959 0 013.598 6 11.99 11.99 0 003 9.749c0 5.592 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.31-.21-2.571-.598-3.751h-.152c-3.196 0-6.1-1.248-8.25-3.286zm0 13.036h.008v.008h-.008v-.008z" /></svg>
          <h1 className="text-2xl font-bold text-slate-800">ClaimFast AI</h1>
        </div>
        <div className="text-sm text-slate-500">Policy #123-456-789</div>
      </div>
    </header>
  );

  const ProgressBar = () => (
    <div className="px-4 sm:px-6 lg:px-8 pt-8 pb-4">
      <ol className="flex items-center w-full">
        {STEPS.map((s, index) => (
            <li key={s.id} className={`flex w-full items-center ${index !== STEPS.length - 1 ? "after:content-[''] after:w-full after:h-1 after:border-b after:border-4 after:inline-block" : ''} ${index <= currentStepIndex ? 'text-blue-600 after:border-blue-600' : 'text-slate-400 after:border-slate-200'}`}>
                <span className={`flex items-center justify-center w-10 h-10 rounded-full shrink-0 ${index <= currentStepIndex ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
                    {index < currentStepIndex || step === 'complete' ? (
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd"></path></svg>
                    ) : (index + 1)}
                </span>
            </li>
        ))}
      </ol>
      <p className="text-center text-slate-600 font-semibold mt-4 text-lg">{STEPS[currentStepIndex]?.name || 'Confirmation'}</p>
    </div>
  );

  const renderContent = () => {
    switch (step) {
      case 'start':
        return (
          <div className="text-center">
            <h2 className="text-3xl font-bold text-slate-800">Start a New Claim</h2>
            <p className="mt-2 text-slate-500">Please select the type of claim you'd like to make.</p>
            <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-6 max-w-2xl mx-auto">
              <div onClick={() => handleStartClaim('auto')} className="p-8 border-2 border-slate-200 rounded-lg text-center cursor-pointer hover:border-blue-600 hover:shadow-lg transition-all duration-300">
                <p className="text-5xl">🚗</p>
                <h3 className="mt-4 text-xl font-bold text-slate-800">Auto Insurance</h3>
                <p className="mt-1 text-slate-500">For cars, motorcycles, and other vehicles.</p>
              </div>
              <div onClick={() => handleStartClaim('property')} className="p-8 border-2 border-slate-200 rounded-lg text-center cursor-pointer hover:border-blue-600 hover:shadow-lg transition-all duration-300">
                <p className="text-5xl">🏠</p>
                <h3 className="mt-4 text-xl font-bold text-slate-800">Home & Property</h3>
                <p className="mt-1 text-slate-500">For your home, contents, and property.</p>
              </div>
            </div>
          </div>
        );
      case 'details':
        return (
          <form onSubmit={handleDetailsSubmit} className="max-w-lg mx-auto">
             <h2 className="text-2xl font-bold text-slate-800 mb-1">Incident Details</h2>
             <p className="text-slate-500 mb-6">Tell us what happened.</p>
            <div className="space-y-4">
              <div>
                <label htmlFor="date" className="block text-sm font-medium text-slate-700">Date of Incident</label>
                <input type="date" id="date" value={claimDetails.date} onChange={e => setClaimDetails({...claimDetails, date: e.target.value})} className="mt-1 block w-full px-3 py-2 bg-white border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500" />
              </div>
              <div>
                <label htmlFor="location" className="block text-sm font-medium text-slate-700">Location (Address or Suburb)</label>
                <input type="text" id="location" placeholder="e.g., 123 Pitt St, Sydney NSW" value={claimDetails.location} onChange={e => setClaimDetails({...claimDetails, location: e.target.value})} className="mt-1 block w-full px-3 py-2 bg-white border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500" />
              </div>
              <div>
                <label htmlFor="description" className="block text-sm font-medium text-slate-700">Description of Incident</label>
                <textarea id="description" rows="4" placeholder="Please describe what happened in as much detail as possible..." value={claimDetails.description} onChange={e => setClaimDetails({...claimDetails, description: e.target.value})} className="mt-1 block w-full px-3 py-2 bg-white border border-slate-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"></textarea>
              </div>
            </div>
            <div className="mt-8 text-right">
                <button type="submit" disabled={!isDetailsFormValid} className="inline-flex items-center px-6 py-3 border border-transparent text-base font-medium rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-slate-400 disabled:cursor-not-allowed">Next: Upload Media</button>
            </div>
          </form>
        );
      case 'upload':
        return (
            <div className="max-w-lg mx-auto text-center">
                <h2 className="text-2xl font-bold text-slate-800 mb-1">Upload Photos & Videos</h2>
                <p className="text-slate-500 mb-6">Our AI needs media to assess the damage. Please upload clear photos and videos.</p>
                {!isUploading ? (
                    <div className="mt-4 p-12 border-2 border-dashed border-slate-300 rounded-lg flex flex-col items-center">
                        <svg className="w-12 h-12 text-slate-400" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5m-13.5-9L12 3m0 0l4.5 4.5M12 3v13.5" /></svg>
                        <p className="mt-2 text-slate-500">Drag & drop files here or</p>
                        <button onClick={handleFileUpload} className="mt-4 inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700">Select Files</button>
                    </div>
                ) : (
                    <div className="mt-8">
                        <p className="text-slate-600 font-medium">Uploading...</p>
                        <div className="w-full bg-slate-200 rounded-full h-2.5 mt-2">
                            <div className="bg-blue-600 h-2.5 rounded-full transition-all duration-300" style={{ width: `${uploadProgress}%` }}></div>
                        </div>
                        <p className="mt-2 text-sm text-slate-500">{uploadProgress}% complete</p>
                        {uploadProgress === 100 && <p className="mt-2 text-emerald-600 font-semibold">Upload successful! Proceeding to assessment...</p>}
                    </div>
                )}
            </div>
        );
       case 'assessing':
        return (
            <div className="text-center max-w-lg mx-auto">
                 <div className="flex justify-center items-center mb-4">
                    <svg className="animate-spin h-10 w-10 text-blue-600" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                </div>
                <h2 className="text-2xl font-bold text-slate-800">AI Damage Assessment in Progress</h2>
                <p className="mt-2 text-slate-500">Our AI is analyzing your photos and videos. This usually takes less than a minute.</p>
            </div>
        );
      case 'results':
        return (
          <div className="max-w-2xl mx-auto">
            <div className="bg-white p-6 rounded-lg shadow-md border border-slate-200">
              <h2 className="text-2xl font-bold text-slate-800 mb-4">Assessment Complete</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className={`p-4 rounded-lg ${assessmentResult.status === 'Pre-approved' ? 'bg-emerald-50 border-emerald-200' : 'bg-amber-50 border-amber-200'} border`}>
                    <p className="text-sm font-medium text-slate-500">Claim Status</p>
                    <p className={`text-xl font-bold ${assessmentResult.status === 'Pre-approved' ? 'text-emerald-600' : 'text-amber-600'}`}>{assessmentResult.status}</p>
                </div>
                <div className="p-4 rounded-lg bg-slate-50 border-slate-200 border">
                    <p className="text-sm font-medium text-slate-500">Fraud Risk</p>
                    <p className="text-xl font-bold text-slate-700">Low ({assessmentResult.fraudScore}/100)</p>
                </div>
                 <div className="p-4 rounded-lg bg-slate-50 border-slate-200 border">
                    <p className="text-sm font-medium text-slate-500">Estimated Repair Cost</p>
                    <p className="text-xl font-bold text-slate-700">{assessmentResult.estimatedCost}</p>
                </div>
                <div className="p-4 rounded-lg bg-slate-50 border-slate-200 border">
                    <p className="text-sm font-medium text-slate-500">Damage Severity</p>
                    <p className="text-xl font-bold text-slate-700">{assessmentResult.severity}</p>
                </div>
              </div>
              <div className="mt-6">
                 <h3 className="text-lg font-semibold text-slate-800">Detected Damage</h3>
                 <ul className="mt-2 space-y-2">
                    {assessmentResult.damages.map((damage, index) => (
                        <li key={index} className="flex items-center text-slate-600">
                           <svg className="h-5 w-5 text-emerald-500 mr-2" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                           {damage}
                        </li>
                    ))}
                 </ul>
              </div>
            </div>
            <div className="mt-8 text-right">
                <button onClick={() => setStep('repairer')} className="inline-flex items-center px-6 py-3 border border-transparent text-base font-medium rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500">Next: Choose a Repairer</button>
            </div>
          </div>
        );
      case 'repairer':
        return (
          <div className="max-w-3xl mx-auto">
            <h2 className="text-2xl font-bold text-slate-800 mb-1">Select a Repair Shop</h2>
            <p className="text-slate-500 mb-6">Choose a pre-approved repairer from our network.</p>
            <div className="space-y-4">
              {repairers.map(r => (
                <div key={r.id} onClick={() => setSelectedRepairer(r.id)} className={`p-4 border-2 rounded-lg flex items-center justify-between cursor-pointer transition-all duration-200 ${selectedRepairer === r.id ? 'border-blue-600 bg-blue-50 shadow-md' : 'border-slate-200 bg-white hover:border-slate-300'}`}>
                  <div>
                    <p className="font-bold text-slate-800">{r.name}</p>
                    <p className="text-sm text-slate-500">{r.location}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm text-slate-600">⭐ {r.rating}</p>
                     <p className="text-sm text-slate-500">{r.distance} away</p>
                  </div>
                </div>
              ))}
            </div>
             <div className="mt-8 text-right">
                <button onClick={handleConfirmBooking} disabled={!selectedRepairer || isBooking} className="inline-flex items-center px-6 py-3 border border-transparent text-base font-medium rounded-md shadow-sm text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:bg-slate-400 disabled:cursor-not-allowed">
                  {isBooking && <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>}
                  {isBooking ? 'Booking...' : 'Confirm Booking'}
                </button>
            </div>
          </div>
        );
      case 'complete':
        return (
            <div className="text-center max-w-lg mx-auto">
                 <div className="flex justify-center items-center mb-4">
                    <div className="bg-emerald-100 rounded-full p-3">
                        <svg className="h-10 w-10 text-emerald-600" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    </div>
                </div>
                <h2 className="text-3xl font-bold text-slate-800">Claim Lodged & Booking Confirmed!</h2>
                <p className="mt-2 text-slate-500">Your claim has been successfully processed. The repair shop has been notified and will contact you within 24 hours to confirm your appointment time.</p>
                <p className="mt-4 text-sm text-slate-500">Claim Reference: <span className="font-mono bg-slate-100 p-1 rounded">CL-2024-8B3D9</span></p>
                <button onClick={() => { setStep('start'); setClaimType(null); setSelectedRepairer(null); setClaimDetails({ date: '', location: '', description: '' }); }} className="mt-8 inline-flex items-center px-4 py-2 border border-slate-300 text-sm font-medium rounded-md shadow-sm text-slate-700 bg-white hover:bg-slate-50">Start a New Claim</button>
            </div>
        );
      default:
        return <div>Invalid Step</div>;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800">
      <Header />
      <main className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {step !== 'start' && <ProgressBar />}
        <div className="mt-8">
            {renderContent()}
        </div>
      </main>
    </div>
  );
}

export default ClaimSubmissionPrototype;

